import { HowToCraft } from '~/ui/items/common/mindOfInstructions'

import backsideVideo01 from './explanation/00.backside01.mp4'
import backsidePicture01 from './explanation/00.backside01.jpg'
import backsideVideo02 from './explanation/00.backside02.mp4'
import backsidePicture02 from './explanation/00.backside02.jpg'
import usageMethod01 from './explanation/01.method01.jpg'
